routes.css:
.pagecraft-root{--c-text:#111311;--c-bg:#f8f6ef;--c-brand:#b7f34a;--c-ink:#111311;--c-muted:#5f6660;--c-muted-i:#b0b7b1;--c-slate:#6f7771;--c-line:#e5e1d6;--c-surface:#ffffff}
.pagecraft-root{--maxw:1200px;--accent:var(--c-brand)}
.pagecraft-root *,.pagecraft-root *::before,.pagecraft-root *::after{box-sizing:border-box}
.pagecraft-root{-webkit-text-size-adjust:100%}
.pagecraft-root{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:16px;line-height:1.6;color:var(--c-text);background:var(--c-bg);-webkit-font-smoothing:antialiased}
.pagecraft-root img,.pagecraft-root video,.pagecraft-root svg{max-width:100%}
.pagecraft-root .pagecraft-skip{
  position:fixed;left:12px;top:12px;z-index:2147483647;padding:10px 14px;
  color:var(--c-bg);background:var(--c-ink);border-radius:6px;text-decoration:none;
  transform:translateY(calc(-100% - 24px));transition:transform .15s ease;
}
.pagecraft-root .pagecraft-skip:focus{transform:translateY(0)}
.pagecraft-root .pagecraft-section{position:relative;width:100%}
.pagecraft-root .pagecraft-container{width:100%;max-width:var(--maxw);margin-left:auto;margin-right:auto;position:relative}
.pagecraft-root .pagecraft-container.full{max-width:none}
.pagecraft-root .pagecraft-row,.pagecraft-root .pagecraft-list{display:flex;flex-wrap:wrap;width:100%}
.pagecraft-root .pagecraft-column{display:flex;flex-direction:column;min-width:0;flex-shrink:1;flex-basis:0%}
.pagecraft-root .pagecraft-box{display:block;width:100%;min-width:0;position:relative}
.pagecraft-root .pagecraft-box.l-flex{display:flex;flex-wrap:wrap}
.pagecraft-root .pagecraft-box.l-grid{display:grid}
.pagecraft-root .pagecraft-box>*{min-width:0}
.pagecraft-root a.pagecraft-box{color:inherit;text-decoration:none}
.pagecraft-root .pagecraft-heading{margin:0;font-family:inherit}
.pagecraft-root .pagecraft-heading a{color:inherit;text-decoration:none}
.pagecraft-root .pagecraft-wysiwyg>:first-child{margin-top:0}
.pagecraft-root .pagecraft-wysiwyg>:last-child{margin-bottom:0}
.pagecraft-root .pagecraft-wysiwyg a{text-decoration:underline;text-underline-offset:2px}
.pagecraft-root .pagecraft-wysiwyg ul,.pagecraft-root .pagecraft-wysiwyg ol{padding-left:1.3em;margin:.7em 0}
.pagecraft-root .pagecraft-wysiwyg h1,.pagecraft-root .pagecraft-wysiwyg h2,.pagecraft-root .pagecraft-wysiwyg h3,.pagecraft-root .pagecraft-wysiwyg h4{margin:.3em 0 .5em;line-height:1.25;font-family:inherit}
.pagecraft-root .pagecraft-wysiwyg blockquote{margin:1em 0;padding-left:1em;border-left:3px solid currentColor;opacity:.85}
.pagecraft-root .pagecraft-button{display:inline-flex;align-items:center;justify-content:center;gap:.5em;text-decoration:none;border:0 solid transparent;cursor:pointer;line-height:1.2;transition:background-color .18s ease,color .18s ease,border-color .18s ease,transform .18s ease;max-width:100%}
.pagecraft-root .pagecraft-button svg{width:1em;height:1em;flex:0 0 auto}
.pagecraft-root .pagecraft-figure{margin:0;display:flex;flex-direction:column}
.pagecraft-root .pagecraft-image{display:block;width:100%;height:auto}
.pagecraft-root .pagecraft-caption{font-size:.82em;opacity:.7;margin-top:.55em}
.pagecraft-root .pagecraft-slider-box{position:relative;width:100%}
.pagecraft-root .pagecraft-slider{
  display:flex;gap:var(--sl-gap,24px);width:100%;
  overflow-x:auto;overscroll-behavior-x:contain;
  scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;
  scrollbar-width:none;padding-bottom:0;
}
.pagecraft-root .pagecraft-slider::-webkit-scrollbar{display:none;width:0;height:0}
.pagecraft-root .pagecraft-slider>[class]{flex:0 0 var(--sl-w,100%);scroll-snap-align:start;min-width:0}
.pagecraft-root .pagecraft-slider>*{scroll-snap-align:start;min-width:0}
.pagecraft-root .pagecraft-slider:focus-visible{outline:3px solid currentColor;outline-offset:3px}
.pagecraft-root .pagecraft-slide-btn{
  position:absolute;top:50%;translate:0 -50%;z-index:2;
  width:36px;height:36px;display:grid;place-items:center;cursor:pointer;
  border:1px solid var(--c-line,#e5e1d6);border-radius:99px;
  background:var(--c-bg,#fff);color:inherit;
}
.pagecraft-root .pagecraft-slide-btn.p{left:-8px;rotate:90deg}
.pagecraft-root .pagecraft-slide-btn.n{right:-8px;rotate:-90deg}
.pagecraft-root .pagecraft-slide-btn[hidden]{display:none}
.pagecraft-root .pagecraft-slide-btn:disabled{opacity:.35;cursor:default}
.pagecraft-root .pagecraft-slider-dots{display:flex;align-items:center;justify-content:center;gap:0;margin-top:16px}
.pagecraft-root .pagecraft-slider-dots[hidden]{display:none}
.pagecraft-root .pagecraft-slider-dot{appearance:none;width:36px;height:36px;padding:0;display:grid;place-items:center;border:0;border-radius:99px;background:transparent;color:var(--c-text,#111311);cursor:pointer}
.pagecraft-root .pagecraft-slider-dot::before{content:"";width:8px;height:8px;border-radius:50%;background:currentColor;opacity:.3;transition:transform .2s ease,opacity .2s ease,background-color .2s ease}
.pagecraft-root .pagecraft-slider-dot:hover::before{opacity:.68}
.pagecraft-root .pagecraft-slider-dot[aria-current=true]::before{background:var(--c-brand,#111311);opacity:1;transform:scale(1.25)}
.pagecraft-root .pagecraft-slider-dot:focus-visible{outline:2px solid var(--c-brand,#111311);outline-offset:0}
@media(max-width:767px){.pagecraft-root .pagecraft-slider-dots{margin-top:10px}
.pagecraft-root .pagecraft-slider-dot{width:44px;height:44px}
}
.pagecraft-root .pagecraft-crumbs ol{
  display:flex;flex-wrap:wrap;align-items:center;gap:var(--cb-gap,8px);
  list-style:none;margin:0;padding:0;
  font-size:var(--cb-size,13px);font-weight:var(--cb-weight,500);
}
.pagecraft-root .pagecraft-crumbs li{display:flex;align-items:center;gap:var(--cb-gap,8px)}
.pagecraft-root .pagecraft-crumbs a{color:var(--cb-color,#5f6660);text-decoration:none}
.pagecraft-root .pagecraft-crumbs a:hover{text-decoration:underline}
.pagecraft-root .pagecraft-crumbs [aria-current]{color:var(--cb-current,#111311)}
.pagecraft-root .pagecraft-crumbs li+li::before{content:"›";color:var(--cb-color,#5f6660);opacity:.6}
.pagecraft-root .pagecraft-crumbs[data-sep=slash] li+li::before{content:"/"}
.pagecraft-root .pagecraft-crumbs[data-sep=dot] li+li::before{content:"·"}
.pagecraft-root .pagecraft-crumbs[data-sep=dash] li+li::before{content:"—"}
.pagecraft-root .pagecraft-code{
  width:100%;margin:0;background:var(--cd-bg,#f4f2ea);color:var(--cd-text,#111311);
  border-radius:var(--cd-radius,10px);overflow:hidden;
}
.pagecraft-root .pagecraft-code-head{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:.55em var(--cd-pad-x,18px);border-bottom:1px solid var(--cd-line,#e5e1d6);
  font-family:var(--cd-ui,system-ui,sans-serif);font-size:.8em;opacity:.75;
}
.pagecraft-root .pagecraft-code-copy{
  font:inherit;cursor:pointer;background:none;border:1px solid var(--cd-line,#e5e1d6);
  border-radius:5px;padding:.2em .6em;color:inherit;
}
.pagecraft-root .pagecraft-code-copy:hover{background:#1113110d}
.pagecraft-root .pagecraft-code-copy[hidden]{display:none}
.pagecraft-root .pagecraft-code pre{
  margin:0;padding:var(--cd-pad,16px 18px);overflow-x:auto;
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  font-size:var(--cd-size,14px);line-height:1.55;tab-size:2;
}
.pagecraft-root .pagecraft-code[data-wrap] pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow-x:visible}
.pagecraft-root .pagecraft-code[data-numbers] pre{counter-reset:pcline}
.pagecraft-root .pagecraft-code-line{display:block;counter-increment:pcline}
.pagecraft-root .pagecraft-code-line::before{
  content:counter(pcline);display:inline-block;width:2.2em;margin-right:1.1em;
  text-align:right;opacity:.4;user-select:none;
}
.pagecraft-root .pc-c-com{color:var(--cd-com,#5f6660);font-style:italic}
.pagecraft-root .pc-c-str{color:var(--cd-str,#2f6f5e)}
.pagecraft-root .pc-c-kw{color:var(--cd-kw,#8a4b2a)}
.pagecraft-root .pc-c-num{color:var(--cd-num,#3a5a9a)}
.pagecraft-root .pc-c-key,.pagecraft-root .pc-c-fn{color:var(--cd-key,#5b4a8a)}
.pagecraft-root .pagecraft-table-wrap{width:100%;overflow-x:auto}
.pagecraft-root .pagecraft-table{
  width:100%;border-collapse:collapse;font-size:var(--tbl-size,15px);
  color:var(--tbl-text,#111311);text-align:left;
}
.pagecraft-root .pagecraft-table caption{
  caption-side:bottom;padding-top:.7em;text-align:left;
  font-size:var(--tbl-caption-size,13px);color:var(--tbl-caption-color,#5f6660);
}
.pagecraft-root .pagecraft-table th,.pagecraft-root .pagecraft-table td{padding:var(--tbl-pad,10px 12px);vertical-align:top}
.pagecraft-root .pagecraft-table thead th{
  background:var(--tbl-head-bg,transparent);color:var(--tbl-head-text,#111311);
  font-weight:var(--tbl-head-weight,600);border-bottom:2px solid var(--tbl-line,#e5e1d6);
}
.pagecraft-root .pagecraft-table tbody th{font-weight:var(--tbl-head-weight,600);color:var(--tbl-head-text,#111311)}
.pagecraft-root .pagecraft-table[data-rules=rows] tbody tr+tr>*{border-top:1px solid var(--tbl-line,#e5e1d6)}
.pagecraft-root .pagecraft-table[data-rules=all] th,.pagecraft-root .pagecraft-table[data-rules=all] td{border:1px solid var(--tbl-line,#e5e1d6)}
.pagecraft-root .pagecraft-table[data-zebra] tbody tr:nth-child(even)>*{background:var(--tbl-zebra,#f8f6ef)}
.pagecraft-root .pagecraft-tabs{width:100%}
.pagecraft-root .pagecraft-tablist{display:flex;flex-wrap:wrap;gap:var(--tb-gap,22px);justify-content:var(--tb-align,flex-start);border-bottom:1px solid var(--tb-line,#e5e1d6)}
.pagecraft-root .pagecraft-tab{
  background:none;border:0;cursor:pointer;padding:var(--tb-pad,10px 2px);margin-bottom:-1px;
  font:inherit;font-size:var(--tb-size,15px);font-weight:var(--tb-weight,500);
  color:var(--tb-off,#5f6660);border-bottom:2px solid transparent;transition:color .16s,border-color .16s;
}
.pagecraft-root .pagecraft-tab.on{color:var(--tb-on,#111311);border-bottom-color:var(--tb-on,#111311)}
.pagecraft-root .pagecraft-tab:focus-visible{outline:3px solid currentColor;outline-offset:2px}
.pagecraft-root .pagecraft-tabpanel{padding-top:var(--tb-body-pad,20px);font-size:var(--tb-body-size,16px);color:var(--tb-body-color,#111311)}
.pagecraft-root .pagecraft-tabpanel>:first-child{margin-top:0}
.pagecraft-root .pagecraft-tabpanel>:last-child{margin-bottom:0}
.pagecraft-root .pagecraft-tabs[data-tabs-ready] [data-tab-idle]{display:none}
.pagecraft-root .pagecraft-pager{display:flex;flex-wrap:wrap;gap:6px;align-items:center;justify-content:center;width:100%;margin-top:2.2em}
.pagecraft-root .pagecraft-page{
  display:inline-flex;align-items:center;justify-content:center;min-width:2.4em;padding:.5em .7em;
  border:1px solid var(--c-line);border-radius:6px;text-decoration:none;color:inherit;font-size:.9em;line-height:1;
}
.pagecraft-root .pagecraft-page.on{background:var(--c-ink);color:var(--c-bg);border-color:var(--c-ink)}
.pagecraft-root .pagecraft-page.off{opacity:.35}
.pagecraft-root .pagecraft-page:focus-visible{outline:3px solid var(--c-brand);outline-offset:2px}
.pagecraft-root .pagecraft-quote{margin:0;display:flex;flex-direction:column;border-left:0 solid transparent}
.pagecraft-root .pagecraft-quote blockquote{margin:0}
.pagecraft-root .pagecraft-quote p{margin:0}
.pagecraft-root .pagecraft-quote p+p{margin-top:.6em}
.pagecraft-root .pagecraft-quote p:first-of-type::before{content:"\201C"}
.pagecraft-root .pagecraft-quote p:last-of-type::after{content:"\201D"}
.pagecraft-root .pagecraft-attrib{font-size:.875rem;line-height:1.5;opacity:.72;margin-top:1em}
.pagecraft-root .pagecraft-attrib a{color:inherit}
.pagecraft-root .pagecraft-video{position:relative;width:100%;overflow:hidden}
.pagecraft-root .pagecraft-video-play{position:absolute;inset:0;width:100%;height:100%;padding:0;border:0;cursor:pointer;background:var(--c-ink);display:block}
.pagecraft-root .pagecraft-video-play img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
.pagecraft-root .pagecraft-video-icon{
  position:absolute;left:50%;top:50%;width:66px;height:66px;margin:-33px 0 0 -33px;border-radius:50%;
  background:var(--c-brand);display:block;transition:transform .18s ease;
}
.pagecraft-root .pagecraft-video-play:focus-visible{outline:3px solid var(--c-brand);outline-offset:2px}
.pagecraft-root .pagecraft-video-icon::after{
  content:"";position:absolute;left:26px;top:21px;border-style:solid;
  border-width:12px 0 12px 19px;border-color:transparent transparent transparent var(--c-ink);
}
.pagecraft-root .pagecraft-video-play:hover .pagecraft-video-icon{transform:scale(1.08)}
.pagecraft-root .pagecraft-video>iframe,.pagecraft-root .pagecraft-video>video{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;object-fit:cover}
.pagecraft-root .pagecraft-nav-menu{display:flex;align-items:center;position:relative}
.pagecraft-root .pagecraft-nav-list{display:flex;align-items:center;gap:var(--nav-gap,26px);list-style:none;margin:0;padding:0}
.pagecraft-root .pagecraft-nav-list li{position:relative}
.pagecraft-root .pagecraft-nav-list .sub-menu{display:none;position:absolute;z-index:65;top:100%;left:0;min-width:190px;margin:0;padding:8px;list-style:none;background:var(--nav-panel,#fff);box-shadow:0 18px 38px -18px rgba(15,23,42,.36)}
.pagecraft-root .pagecraft-nav-list li:hover>.sub-menu,.pagecraft-root .pagecraft-nav-list li:focus-within>.sub-menu{display:block}
.pagecraft-root .pagecraft-nav-list .sub-menu .sub-menu{top:0;left:100%}
.pagecraft-root .pagecraft-nav-list a{display:block;text-decoration:none;color:inherit;transition:color .15s ease,background-color .15s ease}
.pagecraft-root .pagecraft-nav-list a:hover{color:var(--nav-hover,inherit)}
.pagecraft-root .pagecraft-nav-toggle{display:none;align-items:center;justify-content:center;width:40px;height:40px;margin:-8px -8px -8px 0;padding:0;border:0;background:none;color:inherit;cursor:pointer}
.pagecraft-root .pagecraft-nav-icon{position:relative;display:block;width:20px;height:2px;background:currentColor;border-radius:2px;transition:background-color .2s ease}
.pagecraft-root .pagecraft-nav-icon::before,.pagecraft-root .pagecraft-nav-icon::after{content:"";position:absolute;left:0;width:20px;height:2px;background:currentColor;border-radius:2px;transition:transform .2s ease}
.pagecraft-root .pagecraft-nav-icon::before{transform:translateY(-6px)}
.pagecraft-root .pagecraft-nav-icon::after{transform:translateY(6px)}
.pagecraft-root [data-nav].is-open .pagecraft-nav-icon{background-color:transparent}
.pagecraft-root [data-nav].is-open .pagecraft-nav-icon::before{transform:rotate(45deg)}
.pagecraft-root [data-nav].is-open .pagecraft-nav-icon::after{transform:rotate(-45deg)}
.pagecraft-root .pagecraft-form{display:flex;flex-wrap:wrap;gap:var(--f-gap,16px);width:100%}
.pagecraft-root .pagecraft-field{display:flex;flex-direction:column;gap:5px;flex:1 1 100%;min-width:0}
.pagecraft-root .pagecraft-field.half{flex:1 1 calc(50% - var(--f-gap,16px) / 2);min-width:12rem}
.pagecraft-root .pagecraft-field label{font-size:.82em;font-weight:500;color:var(--f-label,inherit)}
.pagecraft-root .pagecraft-field input,.pagecraft-root .pagecraft-field textarea,.pagecraft-root .pagecraft-field select{
  font:inherit;color:var(--f-text,inherit);background:var(--f-bg,#fff);
  border:1px solid var(--f-border,#ddd);border-radius:var(--f-radius,8px);
  padding:var(--f-pad,11px 13px);width:100%;
}
.pagecraft-root .pagecraft-field textarea{resize:vertical}
.pagecraft-root .pagecraft-field input:focus,.pagecraft-root .pagecraft-field textarea:focus,.pagecraft-root .pagecraft-field select:focus{outline:2px solid var(--f-btn-bg,#333);outline-offset:1px}
.pagecraft-root .pagecraft-field-check{flex-direction:row;align-items:center;gap:9px}
.pagecraft-root .pagecraft-field-check input{width:auto;padding:0}
.pagecraft-root .pagecraft-field-check label{font-size:1em}
.pagecraft-root .pagecraft-form-button{
  font:inherit;font-weight:600;cursor:pointer;border:0;align-self:flex-start;flex:0 0 auto;
  background:var(--f-btn-bg,#111);color:var(--f-btn-fg,#fff);
  border-radius:var(--f-radius,8px);padding:var(--f-pad,11px 13px);padding-left:26px;padding-right:26px;
}
.pagecraft-root .pagecraft-form-button:disabled{cursor:not-allowed;opacity:.55}
.pagecraft-root .pagecraft-form-status{flex:1 1 100%;margin:0;font-size:.82em;color:var(--f-label,inherit)}
.pagecraft-root .pagecraft-divider{width:100%;border:0 solid transparent;align-self:stretch}
.pagecraft-root .pagecraft-spacer{width:100%;flex:0 0 auto}
.pagecraft-root .pagecraft-accordion{display:flex;flex-direction:column;gap:var(--ac-gap,0px);width:100%}
.pagecraft-root .pagecraft-accordion-item{border-top:1px solid var(--ac-line,currentColor);border-radius:var(--ac-radius,0px)}
.pagecraft-root .pagecraft-accordion-item:last-child{border-bottom:1px solid var(--ac-line,currentColor)}
.pagecraft-root .pagecraft-accordion-q{
  display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;
  padding:var(--ac-pad,18px) 0;list-style:none;
  font-size:var(--ac-q-size,17px);font-weight:var(--ac-q-weight,600);
  color:var(--ac-q-color,inherit);line-height:1.35;
}
.pagecraft-root .pagecraft-accordion-q::-webkit-details-marker{display:none}
.pagecraft-root .pagecraft-accordion-q::marker{content:""}
.pagecraft-root .pagecraft-accordion-a{
  font-size:var(--ac-a-size,16px);color:var(--ac-a-color,inherit);
  line-height:1.65;padding:0 0 var(--ac-pad,18px);max-width:72ch;
}
.pagecraft-root .pagecraft-accordion-a>:first-child{margin-top:0}
.pagecraft-root .pagecraft-accordion-a>:last-child{margin-bottom:0}
.pagecraft-root .pagecraft-accordion-a p{margin:0 0 .85em}
.pagecraft-root .pagecraft-accordion-mark{
  position:relative;flex:0 0 auto;width:16px;height:16px;
  color:var(--ac-mark,currentColor);transition:transform .2s ease;
}
.pagecraft-root .pagecraft-accordion-mark::before,.pagecraft-root .pagecraft-accordion-mark::after{
  content:"";position:absolute;left:50%;top:50%;background:currentColor;border-radius:1px;
}
.pagecraft-root .pagecraft-accordion-mark::before{width:15px;height:1.8px;margin:-.9px 0 0 -7.5px;transform:none}
.pagecraft-root .pagecraft-accordion-mark::after{width:1.8px;height:15px;margin:-7.5px 0 0 -.9px;transform:none;transition:transform .2s ease}
.pagecraft-root [data-marker=plus] [open]>.pagecraft-accordion-q .pagecraft-accordion-mark::after{transform:scaleY(0)}
.pagecraft-root [data-marker=caret] .pagecraft-accordion-mark::before{
  width:10.5px;height:1.8px;margin:-.9px 0 0 -8.9px;transform:rotate(45deg);transform-origin:right center;
}
.pagecraft-root [data-marker=caret] .pagecraft-accordion-mark::after{
  width:10.5px;height:1.8px;margin:-.9px 0 0 -1.6px;transform:rotate(-45deg);transform-origin:left center;
}
.pagecraft-root [data-marker=caret] [open]>.pagecraft-accordion-q .pagecraft-accordion-mark{transform:rotate(180deg)}
.pagecraft-root .pagecraft-embed{width:100%}
.pagecraft-root .pagecraft-embed>*{max-width:100%}
.pagecraft-root .pagecraft-embed-ratio{position:relative}
.pagecraft-root .pagecraft-embed-ratio>iframe,.pagecraft-root .pagecraft-embed-ratio>video,.pagecraft-root .pagecraft-embed-ratio>embed,.pagecraft-root .pagecraft-embed-ratio>object{
  position:absolute;inset:0;width:100%;height:100%;border:0;
}
.pagecraft-root .pagecraft-icon{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;color:inherit;text-decoration:none}
.pagecraft-root .pagecraft-icon-glyph{
  display:block;flex:0 0 auto;box-sizing:content-box;
  width:var(--icon-size,30px);height:var(--icon-size,30px);stroke-width:var(--icon-stroke,1.75);
}
.pagecraft-root .pagecraft-gallery{display:grid;grid-template-columns:repeat(var(--g-cols,3),minmax(0,1fr));gap:var(--g-gap,12px);width:100%}
.pagecraft-root .pagecraft-gallery-item{margin:0;display:flex;flex-direction:column;min-width:0}
.pagecraft-root .pagecraft-gallery-frame{
  display:block;position:relative;overflow:hidden;
  border-radius:var(--g-radius,10px);background:rgba(17,19,17,.05);
}
.pagecraft-root .pagecraft-gallery-img{display:block;width:100%;height:auto}
.pagecraft-root .pagecraft-gallery-fixed .pagecraft-gallery-frame{aspect-ratio:var(--g-ratio,4 / 3)}
.pagecraft-root .pagecraft-gallery-fixed .pagecraft-gallery-img{height:100%;object-fit:var(--g-fit,cover)}
.pagecraft-root .pagecraft-gallery-caption{font-size:.82em;opacity:.7;margin-top:.5em}
.pagecraft-root .pagecraft-lightbox{
  padding:0;border:0;background:transparent;width:100%;height:100%;
  max-width:100vw;max-height:100vh;overflow:hidden;
}
.pagecraft-root .pagecraft-lightbox::backdrop{background:rgba(10,12,10,.93)}
.pagecraft-root .pagecraft-lightbox-fig{
  margin:0;width:100%;height:100%;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:16px;padding:clamp(16px,4vw,48px);
}
